import React from "react";
import { type LinkProps as ReactLinkProps, Link as RouterLink } from "react-router-dom";
import { type ButtonProps as ChakraButtonProps, Button } from "@chakra-ui/react";

type ButtonProps = ReactLinkProps & ChakraButtonProps;

const isExternalUrl = (to: ReactLinkProps["to"]): boolean => {
  if (typeof to !== "string") return false;
  return /^[a-z][a-z\d+\-.]*:\/\//i.test(to) || to.startsWith("mailto:") || to.startsWith("tel:");
};

function ExternalButtonLink({ onClick, to, ...props }: ButtonProps) {
  const handleClick: React.MouseEventHandler<HTMLButtonElement> = (event) => {
    if (props.disabled) {
      event.preventDefault();
    } else {
      onClick?.(event);
    }
  };
  return (
    <Button
      as="a"
      tabIndex={0}
      {...props}
      {...({ href: to as string } as object)}
      onClick={handleClick}
    />
  );
}

function InternalButtonLink({ onClick, to, ...props }: ButtonProps) {
  const handleClick: React.MouseEventHandler<HTMLButtonElement> = (event) => {
    if (props.disabled) {
      event.preventDefault();
    } else {
      onClick?.(event);
    }
  };
  return <Button as={RouterLink} tabIndex={0} {...props} {...{ to }} onClick={handleClick} />;
}

export const ButtonLink = (props: ButtonProps) => {
  if (isExternalUrl(props.to)) {
    return <ExternalButtonLink {...props} />;
  }
  return <InternalButtonLink {...props} />;
};
